"""
This file contains the page object class for the New Monaco Plan window in the Monaco application.
"""
from interops.libraries.common.state import State
from interops.libraries.monaco.interactions.objects.monaco_new_monaco_plan_objects import MonacoNewMonacoPlanObjects
from interops.libraries.monaco.pages.map_structures_dialog import MapStructures
from interops.libraries.squish_actions import CommonActions
from interops.libraries.monaco.interactions import MonacoDashboard
import time
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MONACO_APP_NAME
from interops.libraries.squish_actions.exceptions import FailedToFindObject

@deco.apply_app_context(application_name=MONACO_APP_NAME)
class NewMonacoPlan():
    """
    Page Object Class for the New Monaco Plan window used for creating new Monaco plan with selected template in Monaco.

    """
    def __init__(self) -> None:
        self.new_plan_name = State(MonacoNewMonacoPlanObjects.new_Plan_Name_Edit)
        self.plan_description =  State(MonacoNewMonacoPlanObjects.new_Plan_Description_Edit)
        self.delivery = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Delivery_ComboBox)
        self.anatomical_site = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Anatomical_Site_ComboBox)
        self.template_name_filter = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Template_Name_Edit)
        self.scan_orientation_head_first = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Scan_Orientation_Head_First)
        self.scan_orientation_feet_first = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Scan_Orientation_Feet_First)
        self.mosaiq_options_course_id = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_MOSAIQ_Options_Course_ID_Edit)
        self.mosaiq_options_plan_intent = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_MOSAIQ_Options_plan_Intent_ComboBox)
        self.mosaiq_options_tolerance_table = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_MOSAIQ_Options_tolerance_Table_ComboBox)
        self.selected_template_name = ""
        self.template = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_TemplateData_TreeItem)
        self.template_tree = CommonActions.find_object(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Templates_Tree)
        self.delivery_beam = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_BeamData_TreeItem_CheckBox)
        self.setup_beam = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_BeamData_TreeItem_CheckBox_2)
        self.tu_chain = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Treatment_Unit_HeaderItem)
        self.energy_chain = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Energy_HeaderItem)
        self.isocenter_chain = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Isocenter_Location_HeaderItem)
        self.port_options_import_beams_only = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Port_Options_Import_Beams_Only_RadioButton)
        self.port_options_retain_template_beam_shapes = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Port_Options_Retain_Template_Beam_Shapes_RadioButton)
        self.port_options_auto_conform_ports = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Port_Options_Auto_conform_Ports_RadioButton)
        self.port_options_auto_conform_to = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Port_Options_Conform_to_ComboBox)
        self.port_options_auto_conform_margin_cm =  State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Port_Options_Margin_Edit)
        self.port_options_auto_conform_with_mlc = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Port_Options_MLC_CheckBox)
        self.setup_reference_point_to_plan_isocenter = State(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Setup_Reference_Point_Set_to_Plan_Isocenter)
        self.combobox_columns_definition = {"Treatment Unit":1, "Modality":2,  "Algorithm":3, "Energy":4, "Isocenter Location":5} #ComboBox columns order: 1 based
        self.edit_columns_definition = {"Map Machine":1, "X(cm)":2, "Y(cm)":3, "Z(cm)":4}  # edit columns order: 1 based
        self.map_machine_column = 2


    def expand_template_tree(self):
        """
        Expand the template tree
        """
        tree_item = self.template.id
        CommonActions.expand_control(tree_item)

    def __toggle_chain(self, obj_map:dict):
        """
        Toggle the chain of the object(the cloumn header) by clicking on it

        :param: obj_map (dict), the object operating on.
        """
        obj = CommonActions.find_object(obj_map)
        CommonActions.left_click_object(obj)
        time.sleep(0.5)

    def toggle_tu_chain(self):
        """
        Toggle chain of the Treatment Unit column
        """
        self.__toggle_chain(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Treatment_Unit_HeaderItem)

    def toggle_energy_chain(self):
        """
        Toggle chain of the Energy column
        """
        self.__toggle_chain(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Energy_HeaderItem)

    def toggle_isocenter_chain(self):
        """
        Toggle chain of the Isocenter Location column
        """
        self.__toggle_chain(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Isocenter_Location_HeaderItem)

    def locate_combobox(self, listviewitem_row_i:int, combobox_col_j:int) -> dict:
        """
        Locate the comboBox

        :params: listviewitem_row_i (int): the listvieew row index,
                  combobox_col_j (int): the comboBox cloumn index

        :return: dict represent of the comboBox object.
        """
        row = MonacoNewMonacoPlanObjects.new_Monaco_Plan_ListView_ListViewItem_i
        row["occurrence"] = listviewitem_row_i
        combobox = MonacoNewMonacoPlanObjects.new_Monaco_Plan_ListView_ListViewItem_i_ComboBox_j
        combobox["occurrence"] = combobox_col_j
        CommonActions.left_click_object(MonacoNewMonacoPlanObjects.new_Monaco_Plan_ListView_ListViewItem_i_ComboBox_j_Arrow_WPFControl)
        time.sleep(0.1)
        return combobox

    def select_combobox(self, listviewitem_row_i:int, combobox_col_j:int, value:str, object_item_type:str):
        """
        Select the comboBox to a given item value with given object item type

        :Params: listviewitem_row_i (int): the listvieew row index
                 combobox_col_j (int): the comboBox cloumn index
                 value (str): selected value
                 object_item_type (str): the type name of the item.

        """
        self.locate_combobox(listviewitem_row_i, combobox_col_j)
        item_obj = CommonActions.find_object({"type": object_item_type, "text": value} , 20000)
        if item_obj is not None:
            CommonActions.mouse_click(item_obj)

    def get_beam_obj(self, listviewitem_row_i:int) -> dict:
        """
        Get the beam object

        :param:  listviewitem_row_i (int): the listvieew row index
        :return: dict, the beam object
        """
        beam = MonacoNewMonacoPlanObjects.new_Monaco_Plan_ListView_Beam_i_Label
        beam["occurrence"] = listviewitem_row_i
        return beam

    def get_beam_name(self, listviewitem_row_i:int):
        """
        Get the beam name of the listview row

        :param: listviewitem_row_i (int): the listvieew row index
        """
        return State(self.get_beam_obj(listviewitem_row_i)).value

    def locate_edit(self, listviewitem_row_i:int, edit_col_j:int) -> State:
        """
        Locate the Edit control at give row and column

        :params: listviewitem_row_i (int): the listvieew row index
                 combobox_col_j (int): the comboBox cloumn index

        :return: the State object of the Edit.
        """
        listviewitem = MonacoNewMonacoPlanObjects.new_Monaco_Plan_ListView_ListViewItem_i
        listviewitem["occurrence"] = listviewitem_row_i
        edit = MonacoNewMonacoPlanObjects.new_Monaco_Plan_ListView_ListViewItem_i_Edit_j
        edit["occurrence"] = edit_col_j
        return State(edit)

    def set_edit(self,listviewitem_row_i:int, edit_col_j:int, value):
        """
        Set value for the edit at position (rowi, colj).

        :params: listviewitem_row_i (int): 1 based listviewitem row number, edit_col_j (int): 1 based edit column number,
                 value (str) to be set
        """
        edit_state = self.locate_edit(listviewitem_row_i, edit_col_j)
        if edit_state.value != value:
           try:
               edit_state.value = value
           except Exception:
               print(f"Failed to change text to '{value}' as the edit is not enabled.")

    def get_combobox_value(self, i:int, j:int)->object:
        """
        Get the value of comboBox at the location (i,j)

        :params: i (int): the listvieew row index,
                 j (int): the comboBox cloumn index
        :return: the value object
        """
        self.combobox_obj = self.locate_combobox(i,j)
        return State(self.combobox_obj).value

    def get_edit_item(self, i:int, j:int) -> object:
        """
        Get the value of Edit at the location (i,j)

        :params: i (int): the listvieew row index,
                 j (int): the edit cloumn index
        :return: the value object
        """
        self.edit_obj = self.locate_edit(i,j)
        return self.edit_obj.value

    def set_edit_item(self,i:int, j:int, value:str):
        """
        Set the edit content to a given value

        :params: i (int): the listvieew row index
                 j (int): the comboBox cloumn index
                 value (str): the value to set

        """
        self.edit_obj = self.locate_edit(i,j)
        self.edit_obj.value = value

    def click_ok(self, confirmToNotification:bool = True):
        """
        Click OK button of the window

        :param: confirmToNotification (bool), if confirm to notification.
        """
        CommonActions.left_click_object(MonacoNewMonacoPlanObjects.new_Monaco_Plan_OK_Button)
        MonacoDashboard.confirm_notification(confirmToNotification)

    def move_scrollbar(self, dx, dy):
        """
        Move the scroll bar

        :params: dx, horizontal distance, minus means leftwards, dy, vertical distance, minus means upwards
        """
        CommonActions.mouse_drag(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Vertical_ScrollBar, dx, dy)

    def set_patient_orientation(self, head_first:bool, confirm_warning: bool):
        """
        Set patient scan orientation

        :param: head_first (bool), True: if head first. False: if feet first
                confirm_warning (bool), True: Yes to warning, False: No to warning
        """

        if head_first:
            self.scan_orientation_head_first.value = True
        else:
            self.scan_orientation_feet_first.value = True

        if CommonActions.find_any_object([MonacoNewMonacoPlanObjects.monaco_Warning_Window]):
            if confirm_warning:
                CommonActions.left_click_object(MonacoNewMonacoPlanObjects.monaco_Warning_Window_Yes_Button)
                orientation = "Head First" if head_first else "Feet First"
                print(f"Scan orientation set to {orientation}")
            else:
                CommonActions.left_click_object(MonacoNewMonacoPlanObjects.monaco_Warning_Window_No_Button)
                orientation = "Head First" if not head_first else "Feet First"
                print(f"Scan orientation reverted back to {orientation}")

    def set_mosaiq_options(self, course_id: str, plan_intent:str, tolerance_table_name):
        """
        Set Mosaiq Options.

        :params:  course_id (str), course id
                  plan_intent (str), plan intent option
                  tolerance_table_name (str), tolerance table name
        """
        self.mosaiq_options_course_id.value = course_id
        self.mosaiq_options_plan_intent.value = plan_intent
        self.mosaiq_options_tolerance_table.value = tolerance_table_name

    def create_plan(self, new_plan_name:str, plan_description:str, head_first:bool, confirm_warning:bool, delivery:str, template:str,
                    anatomical_site:str, delivery_beam_on:bool, setup_beam_on:bool, mosaiq_course_id:str, mosaiq_plan_intent:str,
                    mosaiq_tolerance_table_name:str, default_tu:str, toggle_tu:bool, selected_tu_list:list, default_map_machine_name,
                    set_map_machine_list:list, selected_modality_list:list, default_algorithm, selected_algorithm_list:list, default_energy:str,
                    toggle_energy:bool, selected_energy_list:list, toggle_isocenter:bool, selected_isocenter_list:list, set_x_list:list, set_y_list:list,
                    set_z_list:list, import_beams_only:bool, retain_beam_shape:bool, auto_conform_ports:bool, point_to_isocenter:bool,
                    structure_map: list, remove_from_imrt_constraints:bool,  remove_from_dosimetric_criteria:bool, change_structure_name:bool,
                    auto_conform_to_structure:str="", auto_conform_margin="0.0", auto_conform_with_mlc:bool=False):
        """
        Create plan with the given parameters.

        :params:
                    new_plan_name (str), the new plan name
                    plan_description(str), the plan description
                    head_first (bool), indicating if it is head first orientation, True: head first, False: feet first
                    confirm_warning (bool), indicating the response when the orientation set is not consistent with the image set, True: confirmed, False: cancel it
                    delivery (str), the delivery name
                    template (str), the template or its keyword
                    anatomical_site (str), the anatomical site
                    delivery_beam_on (bool),indicating if delvery beam checked, True: checked on, False: checked off
                    setup_beam_on (bool), indicating if setup beam checked, True: checked on, False: checked off
                    mosaiq_course_id (str), the given mosaiq course id
                    mosaiq_plan_intent (str), the plan intent
                    mosaiq_tolerance_table_name (str), the name of Mosaiq tolerance table
                    default_tu (str), default treatment unit if not filled or selected specially
                    toggle_tu:bool, indicating if need to toggle Treatment Unit column so it will change from connected to broken or verse vice.
                    selected_tu_list (list), the seleted Treatment Unit list, the first item of an item is the row index, the second is its name
                    default_map_machine_name (str), default map machine name if not available yet
                    set_map_machine_list (list), set machine name map, each is a pair of the mapping of machine names.
                    selected_modality_list (list), selected Modalities
                    default_algorithm (str), default algorithm,
                    selected_algorithm_list (list),  selected algorithms
                    default_energy (str), default energy
                    toggle_energy (bool), indicating if need to toggle Energy column so it will change from connected to broken or verse vice.
                    selected_energy_list (list), selected energy list
                    toggle_isocenter (bool),  indicating if need to toggle Isocenter Location column so it will change from connected to broken or verse vice.
                    selected_isocenter_list (list),  selected isocenter locations
                    set_x_list (list), set the location X value list specifically
                    set_y_list (list), set the location Y value list specifically
                    set_z_list (list), set the location Z value list specifically
                    import_beams_only (bool), indicting if just to import beams only, True: Import beams only, False: not only beams
                    retain_beam_shape (bool), indicating if need to retain template beam shape, True: retain, False: not retain
                    auto_conform_ports (bool), indicating if need to conform ports to a structure, True: use auto conform, False: not use auto conform
                    point_to_isocenter (bool), indicating if need to set setup reference point to plan isocenter, True: set to iscocenter, False: not set
                    structure_map (list), the list of structure maps, each map is the mapping machine pair,
                    remove_from_imrt_constraints (bool), indicating if the unmapped structure should be removed from IMRT Constraints, True: remove, False: Not remove
                    remove_from_dosimetric_criteria: indicating if the unmapped structure should be removed from IMRT Constraints, True: Remove, False: not remove
                    change_structure_name (bool), indicating if need to change the structure names, True: Change, False: not change
                    auto_conform_to_structure (str), auto conform to structure name, default to empty when not use auto conform ports,
                    auto_conform_margin (str), the margin value string, default to '0.00' when not use auto conform ports
                    auto_conform_with_mlc (bool), if with MLC. default to False when not use auto conform ports, True: with MLC, False: without MLC

        """

        self.new_plan_name.value = new_plan_name
        self.plan_description.value = plan_description
        self.delivery.value = delivery
        self.anatomical_site.value = anatomical_site
        self.template_name_filter.value = template
        self.expand_template_tree()
        self.delivery_beam.value = delivery_beam_on
        if setup_beam_on:
            self.setup_beam.value = setup_beam_on

        self.set_patient_orientation(head_first, confirm_warning)

        self.set_mosaiq_options(mosaiq_course_id, mosaiq_plan_intent, mosaiq_tolerance_table_name)

        if default_tu:
            self.select_combobox(1, self.combobox_columns_definition["Treatment Unit"], default_tu , "ComboBoxItem")

        if default_map_machine_name:
            self.set_edit(1, self.edit_columns_definition["Map Machine"], default_map_machine_name)
        elif self.get_edit_item(1, self.edit_columns_definition["Map Machine"]) == "":
            tu_name = self.get_combobox_value(1, self.combobox_columns_definition["Treatment Unit"])
            self.set_edit(1, self.edit_columns_definition["Map Machine"], tu_name)

        if default_algorithm:
            self.select_combobox(1, self.combobox_columns_definition["Algorithm"], default_algorithm, "Label")

        if default_energy:
            self.select_combobox(1, self.combobox_columns_definition["Energy"], default_energy, "Label")

        if toggle_tu:
            self.toggle_tu_chain()
        if toggle_energy:
            self.toggle_energy_chain()
        if toggle_isocenter:
            self.toggle_isocenter_chain()

        for i in range(len(selected_tu_list)):
            self.select_combobox(selected_tu_list[i][0], self.combobox_columns_definition["Treatment Unit"], selected_tu_list[i][1] , "ComboBoxItem")
        for i in range(len(set_map_machine_list)):
            self.set_edit(set_map_machine_list[i][0], self.edit_columns_definition["Map Machine"], set_map_machine_list[i][1])
        for i in range(len(selected_energy_list)):
            self.select_combobox(selected_energy_list[i][0], self.combobox_columns_definition["Energy"], selected_energy_list[i][1], "Label")
        for i in range(len(selected_modality_list)):
            self.select_combobox(selected_modality_list[i][0], self.combobox_columns_definition["Modality"], selected_modality_list[i][1] , "Label")
        for i in range(len(selected_algorithm_list)):
            self.select_combobox(selected_algorithm_list[i][0], self.combobox_columns_definition["Algorithm"], selected_algorithm_list[i][1], "Label")
        for i in range(len(selected_isocenter_list)):
            self.select_combobox(selected_isocenter_list[i][0], self.combobox_columns_definition["Isocenter Location"], selected_isocenter_list[i][1], "ComboBoxItem")

        #Move scrollbar to show the upper row
        scrollbar = CommonActions.find_any_object([MonacoNewMonacoPlanObjects.new_Monaco_Plan_Vertical_ScrollBar])
        if scrollbar:
            self.move_scrollbar(0, -10)

        for i in range(len(set_x_list)):
            self.set_edit(set_x_list[i][0], self.edit_columns_definition["X(cm)"], set_x_list[i][1])
        for i in range(len(set_y_list)):
            self.set_edit(set_y_list[i][0], self.edit_columns_definition["Y(cm)"], set_y_list[i][1])
        for i in range(len(set_z_list)):
            self.set_edit(set_z_list[i][0], self.edit_columns_definition["Z(cm)"], set_z_list[i][1])

        if import_beams_only:
            self.port_options_import_beams_only.value = True
        elif retain_beam_shape:
            self.port_options_retain_template_beam_shapes.value = True
        elif auto_conform_ports and auto_conform_margin:
            try:
                self.port_options_auto_conform_ports.value = True
                self.port_options_auto_conform_to.value = auto_conform_to_structure
                self.port_options_auto_conform_margin_cm.value = auto_conform_margin
                try:
                    self.port_options_auto_conform_with_mlc.value = auto_conform_with_mlc
                except Exception:
                    print("State unable to change as the MLC CheckBox is not enabled.")
            except Exception:
                print("State unable to change as the Auto-conform RadioButton is not enabled.")

        self.setup_reference_point_to_plan_isocenter.value = point_to_isocenter

        self.click_ok()

        try:
            #map structure info
            self.map_structure = MapStructures()

            for item in structure_map:
                self.map_structure.map_structure(self.map_machine_column, item[0], item[1])
            time.sleep(1)
            try:
                self.map_structure.remove_from_imrt_constraints.value = remove_from_imrt_constraints
            except Exception:
                print("State unable to change as the IMRT Constraints button is not enabled.")
            try:
                self.map_structure.remove_from_dosimetric_criteria.value = remove_from_dosimetric_criteria
            except Exception:
                print("State unable to change as the Dosimetric Criteria button is not enabled.")
            try:
                self.map_structure.change_structure_name.value = change_structure_name
            except Exception:
                print("State unable to change as the Change Structure Name button is not enabled.")
            self.map_structure.click_ok()
        except FailedToFindObject:
            pass

        print("done.")
